#!/usr/bin/env python3
# Some portions generated by Codex. Depth and six-arm interaction independent-fork analysis, no sample deletion.
import pathlib,sys,json,statistics,re,math
root=pathlib.Path(sys.argv[1])
def records(p):
 out=[]
 for l in p.read_text().splitlines():
  if l.startswith('audit '):out.append(dict(t.split('=',1) for t in l.split()[1:]))
 if not out:raise ValueError(f'Missing result records: {p}')
 return out
results={}
for line in (root/'cells.tsv').read_text().splitlines():
 if not line or line.startswith('#'):continue
 cell,regime,shape,adjacency,groups,family=line.split('\t')
 armnames=('A','AD') if family=='primary' else ('A','AD','C0','C0D','C1','C1D')
 if len(sys.argv)>2 and cell!=sys.argv[2]:continue
 ref=records(root/f'{cell}-reference-A.log')[0]
 fs=[]
 pattern=re.compile(re.escape(cell)+r'-\d{2}-(A|AD|C0|C0D|C1|C1D)\.log$')
 for f in sorted(root.iterdir()):
  m=pattern.fullmatch(f.name)
  if not m:continue
  allrows=records(f); measured=[r for r in allrows if int(r['run'])>=0]
  if len(allrows)!=30 or len(measured)!=10:raise ValueError(f'Incomplete fork: {f}')
  for r in allrows:
   if any(r[k]!=ref[k] for k in ('rows','checksum','checksum2')):raise ValueError(f'Result mismatch: {f}')
  vals=[int(r['totalNs'])/1e6 for r in measured];alloc=[]
  for l in f.read_text().splitlines():
   if l.startswith('run='):
    d=dict(t.split('=',1) for t in l.split() if '=' in t)
    if int(d['run'])>=0:alloc.append(int(d['threadAllocated']))
  if len(alloc)!=10:raise ValueError(f'Missing allocations: {f}')
  pauses=[float(x) for x in re.findall(r'Pause[^\n]*? ([0-9.]+)ms$',pathlib.Path(str(f)+'.gc.log').read_text(),re.M)]
  fs.append({'file':f.name,'arm':m[1],'meanMs':statistics.mean(vals),'minMs':min(vals),'maxMs':max(vals),'byIndexMs':vals,
             'firstRowMs':statistics.mean(int(r['firstRowNs'])/1e6 for r in measured),'allocationMeanBytes':statistics.mean(alloc),
             'wholeJvmGc':{'count':len(pauses),'totalPauseMs':sum(pauses),'maxPauseMs':max(pauses,default=0),'includesWarmup':True}})
 if len(fs)!=4*len(armnames):raise ValueError(f'Incomplete cell: {cell}')
 arms={}
 for arm in armnames:
  ff=[f for f in fs if f['arm']==arm]
  if len(ff)!=4:raise ValueError((cell,arm))
  means=[f['meanMs'] for f in ff]
  arms[arm]={'meanMs':statistics.mean(means),'forkMinMs':min(means),'forkMaxMs':max(means),
             'firstRowMeanMs':statistics.mean(f['firstRowMs'] for f in ff),'allocationMeanBytes':statistics.mean(f['allocationMeanBytes'] for f in ff),
             'measuredIndexMeans':[statistics.mean(f['byIndexMs'][i] for f in ff) for i in range(10)]}
 contrasts={};pairs=[('AD','A')] if family=='primary' else [('AD','A'),('C0D','C0'),('C1D','C1'),('C0','A'),('C1','C0'),('C0D','A'),('C1D','A')]
 for t,c in pairs:
  a,b=arms[c]['meanMs'],arms[t]['meanMs'];contrasts[t+'/'+c]={'latencyReductionPercent':100*(1-b/a),'throughputIncreasePercent':100*(a/b-1)}
 blocks=[]
 for i in range(0,len(fs),len(armnames)):
  m={f['arm']:f['meanMs'] for f in fs[i:i+len(armnames)]}
  if set(m)!=set(arms):raise ValueError(f'Unbalanced block {cell} {i}')
  blocks.append({t+'/'+c:100*(1-m[t]/m[c]) for t,c in pairs})
 interactions={}
 if family=='interaction':
  # Difference in within-block log depth effects. Negative means depth has a larger speedup in C than A.
  for prefix in ('C0','C1'):
   values=[]
   for i in range(0,len(fs),len(armnames)):
    m={f['arm']:f['meanMs'] for f in fs[i:i+len(armnames)]}
    values.append(math.log(m[prefix+'D']/m[prefix])-math.log(m['AD']/m['A']))
   interactions[prefix]={'blockLogRatioDifferences':values,'meanLogRatioDifference':statistics.mean(values),
                         'note':'Negative favors added depth effect on cancellation configuration; not an absolute win versus A'}
 results[cell]={'configuration':{'regime':regime,'shape':shape,'adjacency':adjacency,'groups':int(groups),'family':family},
                'reference':{k:ref[k] for k in ('rows','checksum','checksum2')},'arms':arms,'interactions':interactions,'contrasts':contrasts,'blocks':blocks,'forks':fs}
print(json.dumps({'scope':'incumbent combined D vs isolated read depth; separate cancellation interaction, not main; diagnostics separate','cells':results},indent=2))
